      "notes": "Luritja (ISO 639-3: piu, Glottolog: pint1250, AIATSIS: C7.1) is a Western Desert (Pama-Nyungan) dialect spoken in the Northern Territory, Australia. Wikipedia Luritja language article: spoken around Papunya, Kings Canyon, Aputula; areas around Papunya including Mount Liebig (Papunya Luritja); areas around Aputula and Maryvale (Titjikala Luritja); area around Ulpanyali and Watarrka National Park (Southern Luritja); variety spoken at Kintore (Pintupi/Luritja). MacDonnell Regional Council: Haasts Bluff (Ikuntji) - mostly Luritja speakers; Mount Liebig (Watiyawanu) - majority Luritja; Papunya (Warumpi) - mainly Luritja speakers; Kintore (Walungurru) - small population of Luritja; Titjikala - Luritja speakers; Aputula (Finke) - Southern Luritja speakers. ANU text: Mount Liebig and Papunya are part of Pintupi-Luritja settlements with at least 16 outstations. Removed non-settlements: Kings Canyon (same as Watarrka), Warumpi (same as Papunya). 8 verified seeds remain; below 25-seed floor so status stays WAITING."
